import {Reports} from '../../src/features/reports.ts';import {Repository} from '../../src/domain/repository.ts';import catalog from '../../src/data/catalog.json';import samples from './measurements.json';import {recordBlank,makeDraft} from '../../src/domain/model.ts';import {loadExperimentKnowledge} from '../../src/platform/ai-context.ts';import type {Experiment} from '../../src/domain/types.ts';
export async function createImportReviewFixture(){const exp=catalog.experiments.find(e=>e.sourceId==='电容与高电阻的测量') as Experiment,doc={...recordBlank(exp),draft:makeDraft(exp.schema,(samples as any)[exp.id])},profile={name:'测试',studentId:'TEST',className:'模拟'},files=new Map<string,string>(),repo=new Repository({read:async k=>files.get(k)??null,write:async(k,v)=>{files.set(k,v)},remove:async k=>{files.delete(k)}});let calls=0,values:Record<string,unknown>={};const view=new Reports(repo,{context:()=>({exp,doc,profile,photo:null,blocked:false}),flush:async()=>{},notice:()=>{},jump:()=>{},configureAI:()=>{},upload:()=>{},confirm:async()=>false},{status:async()=>({hasKey:true}),skills:async()=>[],knowledge:loadExperimentKnowledge,complete:async(_slot,messages)=>{calls++;const system=String(messages[0].content),after=system.split('【本机报告引擎计算结果】')[1];if(after){const line=after.split('\n').find(s=>s.trim().startsWith('{'));if(line)values=JSON.parse(line);}const text=system.includes('【问答格式】')?JSON.stringify({answers:['依据本实验原理进行分析。']}):'润色 '+String(messages[1].content).split('原文：').slice(1).join('原文：');return {text,elapsedMs:1};}});await view.open();return {state:()=>({calls,values,working:(view as any).phase!=='idle'||!!(view as any).aiController||(view as any).batchPolish.isBusy}),settings:()=>repo.loadReportSettings(exp.id),history:()=>repo.listAIHistory(exp.id),saved:async()=>{const r=(await repo.loadReport(exp)).value;return r?{generation:r.generation,notices:r.notices}:null;},reopen:async()=>{view.close();await view.open();},clearCache:()=>{(view as any).calculationCache=null;},change:()=>doc.date=doc.date==='2026-10-27'?'2026-10-28':'2026-10-27'};}
